def triton_per_thread_matrix_vector_dot(in_out_y, A, x, alpha, beta,
    num_threads, num_rows, num_cols):
    thread_id = num_threads * get_raw_stream() + torch._C._dynamo.guards.
        get_thread_id()
    y_ptr = in_out_y + thread_id
    x_ptr = x
    y_out_ptr = in_out_y + thread_id
