            triton_math.load(A + i * num_rows + thread_id, 0))
    y_out_ptr[0] = triton_math.mul(alpha, y_out_ptr[0])
    y_ptr[0] = triton_math.mul(beta, triton_math.load(y_ptr, 0))
    y_out_ptr[0] += y_ptr[0]
    for i in range(num_rows):
        y_out_ptr[0] += triton_math.mul(triton_math.load(y_ptr + i, 0),
            triton_math.load(x_ptr + i, 0))
    triton_math.store(y_out_ptr, y_out_ptr[0])


